import assert from "node:assert/strict";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";

import {
  MARKER,
  OWNED_HOOKS,
  isOwnedHook,
  planInstall,
  postCheckoutHook,
  readHookFrom,
} from "./install-hooks.mjs";

const PRE_COMMIT_SHIM =
  "#!/usr/bin/env bash\n# File generated by pre-commit: https://pre-commit.com\nexec pre-commit hook-impl --hook-type=post-checkout\n";

const withHooksDir = (files, run) => {
  const dir = mkdtempSync(join(tmpdir(), "install-hooks-"));
  try {
    for (const [name, body] of Object.entries(files)) {
      writeFileSync(join(dir, name), body, "utf8");
    }
    run(dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
};

const readerFor = (files) => (hook) => files[hook] ?? null;

// The whole point of moving this hook off pre-commit. If the generated hook
// routed back through pre-commit, the snapshot-and-restore of the working tree
// would come with it and nothing would have changed.
test("the generated post-checkout hook does not invoke pre-commit", () => {
  const body = postCheckoutHook();
  assert.doesNotMatch(
    body,
    /pre-commit hook-impl/,
    "routing through pre-commit reinstates the working-tree snapshot",
  );
  assert.match(body, /worktree-owner\.mjs --stage=post-checkout/);
});

// Checking out a commit that predates the script — or any tree without it —
// must not spray an error over an ordinary checkout. Git ignores this hook's
// exit code for the checkout it already performed, so failing loudly would buy
// nothing but noise.
test("the generated hook exits quietly when its script or node is absent", () => {
  const body = postCheckoutHook();
  assert.match(body, /\[ -f scripts\/worktree-owner\.mjs \] \|\| exit 0/);
  assert.match(body, /command -v node > \/dev\/null 2>&1 \|\| exit 0/);
});

test("the generated hook names its generator so a reinstall recognises it", () => {
  assert.ok(postCheckoutHook().includes(MARKER));
  assert.equal(isOwnedHook(postCheckoutHook()), true);
});

test("a hook this script did not write is not treated as ours", () => {
  assert.equal(isOwnedHook(PRE_COMMIT_SHIM), false);
  assert.equal(isOwnedHook(null), false, "absent");
  assert.equal(isOwnedHook("#!/bin/sh\necho hand-written\n"), false);
});

test("an absent hook is planned as a create", () => {
  assert.deepEqual(planInstall(readerFor({})), [
    { hook: "post-checkout", action: "create", replacing: null },
  ]);
});

// The case that decides whether an existing clone is actually fixed. Every
// checkout made before this change has pre-commit's post-checkout shim sitting
// there, so an installer that only created missing hooks would leave the
// snapshot behaviour in place on every machine that already had one.
test("pre-commit's existing shim is planned as a replace, and named", () => {
  assert.deepEqual(
    planInstall(readerFor({ "post-checkout": PRE_COMMIT_SHIM })),
    [
      {
        hook: "post-checkout",
        action: "replace",
        replacing: "pre-commit's generated shim",
      },
    ],
  );
});

test("an unrecognised hook is replaced too, and reported as unrecognised", () => {
  const plan = planInstall(
    readerFor({ "post-checkout": "#!/bin/sh\nexit 0\n" }),
  );
  assert.equal(plan[0].action, "replace");
  assert.equal(plan[0].replacing, "an unrecognised hook");
});

// Reinstalling must be a no-op, or `make setup` churns the hooks directory on
// every run and a genuine change becomes invisible in the noise.
test("installing over our own hook plans no change", () => {
  assert.deepEqual(
    planInstall(readerFor({ "post-checkout": postCheckoutHook() })),
    [{ hook: "post-checkout", action: "current" }],
  );
});

test("planning reads hooks off a real directory", () => {
  withHooksDir({ "post-checkout": PRE_COMMIT_SHIM }, (dir) => {
    const plan = planInstall(readHookFrom(dir));
    assert.equal(plan[0].action, "replace");
    assert.equal(
      readFileSync(join(dir, "post-checkout"), "utf8"),
      PRE_COMMIT_SHIM,
    );
  });
});

test("post-checkout is the only hook this script claims", () => {
  assert.deepEqual(OWNED_HOOKS, ["post-checkout"]);
});
